INSERT INTO lessons (id, course_id, unit_id, position, title, version) VALUES
  ('00000000-0000-0000-0000-000000260001', '00000000-0000-0000-0000-0000000000c0', '00000000-0000-0000-0000-000000260000', 1, 'Food Words', 1),
  ('00000000-0000-0000-0000-000000260002', '00000000-0000-0000-0000-0000000000c0', '00000000-0000-0000-0000-000000260000', 2, 'Ordering Food', 1),
  ('00000000-0000-0000-0000-000000260003', '00000000-0000-0000-0000-0000000000c0', '00000000-0000-0000-0000-000000260000', 3, 'Dinner with Anna', 1),
