INSERT INTO lesson_items (id, lesson_id, position, kind, payload) VALUES
  ('00000000-0000-0000-0000-000000260010', '00000000-0000-0000-0000-000000260001', 1, 'text', '{"phrase": "menu", "translation": {"fa": "منو", "ckb": "مینیو"}, "example": "Can I see the menu, please?", "example_translation": {"fa": "می‌توانم منو را ببینم، لطفاً؟", "ckb": "دەتوانم مینیوەکە ببینم، تکایە؟"}, "image": "/content/restaurant/menu.webp"}'),
  ('00000000-0000-0000-0000-000000260011', '00000000-0000-0000-0000-000000260001', 2, 'text', '{"phrase": "pasta", "translation": {"fa": "پاستا", "ckb": "پاستا"}, "example": "The pasta is very good here.", "example_translation": {"fa": "پاستای این‌جا خیلی خوب است.", "ckb": "پاستای ئێرە زۆر باشە."}, "image": "/content/restaurant/pasta.webp"}'),
  ('00000000-0000-0000-0000-000000260012', '00000000-0000-0000-0000-000000260001', 3, 'text', '{"phrase": "Quick check!", "translation": {"fa": "چکِ سریع!", "ckb": "پشکنینی خێرا!"}}'),
  ('00000000-0000-0000-0000-000000260015', '00000000-0000-0000-0000-000000260001', 4, 'text', '{"phrase": "pizza", "translation": {"fa": "پیتزا", "ckb": "پیتزا"}, "example": "Two pizzas, please.", "example_translation": {"fa": "دو پیتزا، لطفاً.", "ckb": "دوو پیتزا، تکایە."}, "image": "/content/restaurant/pizza.webp"}'),
  ('00000000-0000-0000-0000-000000260016', '00000000-0000-0000-0000-000000260001', 5, 'text', '{"phrase": "water", "translation": {"fa": "آب", "ckb": "ئاو"}, "example": "A glass of water, please.", "example_translation": {"fa": "یک لیوان آب، لطفاً.", "ckb": "پەرداخێک ئاو، تکایە."}, "image": "/content/restaurant/water.webp"}'),
  ('00000000-0000-0000-0000-000000260017', '00000000-0000-0000-0000-000000260001', 6, 'text', '{"phrase": "waiter", "translation": {"fa": "گارسون", "ckb": "گارسۆن"}, "example": "The waiter is very friendly.", "example_translation": {"fa": "گارسون خیلی مهربان است.", "ckb": "گارسۆنەکە زۆر میهرەبانە."}, "image": "/content/restaurant/waiter.webp"}'),
  ('00000000-0000-0000-0000-000000260018', '00000000-0000-0000-0000-000000260001', 7, 'text', '{"phrase": "Let''s practice!", "translation": {"fa": "بیا تمرین کنیم!", "ckb": "با ڕاهێنان بکەین!"}}'),
  ('00000000-0000-0000-0000-00000026001c', '00000000-0000-0000-0000-000000260002', 1, 'text', '{"phrase": "I would like the pasta, please.", "translation": {"fa": "من پاستا می‌خواهم، لطفاً.", "ckb": "من پاستام دەوێت، تکایە."}, "example": "I would like the pasta, please.", "example_translation": {"fa": "من پاستا می‌خواهم، لطفاً.", "ckb": "من پاستام دەوێت، تکایە."}, "image": "/content/restaurant/pasta.webp"}'),
  ('00000000-0000-0000-0000-00000026001d', '00000000-0000-0000-0000-000000260002', 2, 'text', '{"phrase": "Can I have the menu?", "translation": {"fa": "می‌توانم منو را داشته باشم؟", "ckb": "دەتوانم مینیوەکەم پێ بدرێت؟"}, "example": "Excuse me, can I have the menu?", "example_translation": {"fa": "ببخشید، می‌توانم منو را داشته باشم؟", "ckb": "ببورە، دەتوانم مینیوەکەم پێ بدرێت؟"}, "image": "/content/restaurant/menu.webp"}'),
  ('00000000-0000-0000-0000-00000026001e', '00000000-0000-0000-0000-000000260002', 3, 'text', '{"phrase": "Quick check!", "translation": {"fa": "چکِ سریع!", "ckb": "پشکنینی خێرا!"}}'),
  ('00000000-0000-0000-0000-000000260021', '00000000-0000-0000-0000-000000260002', 4, 'text', '{"phrase": "The bill, please.", "translation": {"fa": "صورت‌حساب، لطفاً.", "ckb": "پسوولەکە، تکایە."}, "example": "Can we have the bill, please?", "example_translation": {"fa": "می‌شود صورت‌حساب را بیاورید، لطفاً؟", "ckb": "دەکرێت پسوولەکەمان بۆ بهێنن، تکایە؟"}, "image": "/content/restaurant/coffee.webp"}'),
  ('00000000-0000-0000-0000-000000260022', '00000000-0000-0000-0000-000000260002', 5, 'text', '{"phrase": "I would like ... , please.", "translation": {"fa": "من ... می‌خواهم، لطفاً.", "ckb": "من ...م دەوێت، تکایە."}, "example": "I would like a coffee, please.", "example_translation": {"fa": "یک قهوه می‌خواهم، لطفاً.", "ckb": "قاوەیەکم دەوێت، تکایە."}, "note": {"fa": "برای درخواستِ مؤدبانه از «I would like…» استفاده کن — از «I want» مؤدبانه‌تر است.", "ckb": "بۆ داواکاری بە ڕێزەوە «I would like…» بەکاربهێنە — لە «I want» ڕێزدارترە."}}'),
  ('00000000-0000-0000-0000-000000260023', '00000000-0000-0000-0000-000000260002', 6, 'text', '{"phrase": "Your turn!", "translation": {"fa": "نوبتِ توست!", "ckb": "نۆرەی تۆیە!"}}'),
  ('00000000-0000-0000-0000-000000260027', '00000000-0000-0000-0000-000000260003', 1, 'video', '{"url": "/content/restaurant/at-the-restaurant.mp4", "title": "Anna orders dinner", "poster": "/content/restaurant/pasta.webp"}'),
  ('00000000-0000-0000-0000-000000260028', '00000000-0000-0000-0000-000000260003', 2, 'mini_story', '{"narrator": "Anna is at a restaurant. She says: “Good evening! A table for two, please.” The waiter brings the menu. Anna orders the pasta and a glass of water.", "prompt": "What does Anna order?", "translation": {"fa": "آنا در رستوران است. می‌گوید: «عصر به‌خیر! یک میز برای دو نفر، لطفاً.» گارسون منو را می‌آورد. آنا پاستا و یک لیوان آب سفارش می‌دهد.", "ckb": "ئانا لە چێشتخانەیە. دەڵێت: «ئێوارە باش! مێزێک بۆ دوو کەس، تکایە.» گارسۆنەکە مینیوەکە دەهێنێت. ئانا پاستا و پەرداخێک ئاو داوا دەکات."}}'),
  ('00000000-0000-0000-0000-00000026002b', '00000000-0000-0000-0000-000000260003', 3, 'text', '{"phrase": "Listen carefully!", "translation": {"fa": "با دقت گوش کن!", "ckb": "بە وردی گوێ بگرە!"}}'),
  ('00000000-0000-0000-0000-00000026002e', '00000000-0000-0000-0000-000000260004', 1, 'text', '{"phrase": "Restaurant review!", "translation": {"fa": "مرورِ رستوران!", "ckb": "پێداچوونەوەی چێشتخانە!"}}')
INSERT INTO exercises (id, lesson_item_id, type, prompt, answer_key, difficulty) VALUES
  ('00000000-0000-0000-0000-000000260013', '00000000-0000-0000-0000-000000260012', 'match_image', '{"left": ["menu", "pasta"], "right": ["/content/restaurant/menu.webp", "/content/restaurant/pasta.webp"]}', '{"pairs": [["menu", "/content/restaurant/menu.webp"], ["pasta", "/content/restaurant/pasta.webp"]]}', 1),
  ('00000000-0000-0000-0000-000000260014', '00000000-0000-0000-0000-000000260012', 'mcq', '{"question": "You want to choose food. You ask for the ...", "options": ["menu", "water", "waiter"]}', '{"correct": 0}', 1),
  ('00000000-0000-0000-0000-000000260019', '00000000-0000-0000-0000-000000260018', 'match_image', '{"left": ["pizza", "water", "waiter"], "right": ["/content/restaurant/pizza.webp", "/content/restaurant/water.webp", "/content/restaurant/waiter.webp"]}', '{"pairs": [["pizza", "/content/restaurant/pizza.webp"], ["water", "/content/restaurant/water.webp"], ["waiter", "/content/restaurant/waiter.webp"]]}', 1),
  ('00000000-0000-0000-0000-00000026001a', '00000000-0000-0000-0000-000000260018', 'fill_blank', '{"text": "A glass of ____, please."}', '{"answers": ["water"]}', 1),
  ('00000000-0000-0000-0000-00000026001b', '00000000-0000-0000-0000-000000260018', 'true_false', '{"statement": "The waiter brings your food."}', '{"answer": true}', 1),
  ('00000000-0000-0000-0000-00000026001f', '00000000-0000-0000-0000-00000026001e', 'fill_blank', '{"text": "I would ____ the pasta, please."}', '{"answers": ["like"]}', 1),
  ('00000000-0000-0000-0000-000000260020', '00000000-0000-0000-0000-00000026001e', 'sentence_builder', '{"words": ["Can", "I", "have", "the", "menu"]}', '{"order": ["Can", "I", "have", "the", "menu"]}', 1),
  ('00000000-0000-0000-0000-000000260024', '00000000-0000-0000-0000-000000260023', 'dictation', '{"audio": "/content/restaurant/order-pasta.mp3", "hint": "Type what you hear."}', '{"answers": ["I would like the pasta, please.", "I would like the pasta please", "i would like the pasta please"]}', 1),
  ('00000000-0000-0000-0000-000000260025', '00000000-0000-0000-0000-000000260023', 'sentence_builder', '{"words": ["The", "bill", "please"]}', '{"order": ["The", "bill", "please"]}', 1),
  ('00000000-0000-0000-0000-000000260026', '00000000-0000-0000-0000-000000260023', 'reorder', '{"words": ["I", "would", "like", "the", "pizza"]}', '{"order": ["I", "would", "like", "the", "pizza"]}', 1),
  ('00000000-0000-0000-0000-000000260029', '00000000-0000-0000-0000-000000260028', 'mcq', '{"question": "What does Anna order?", "options": ["Pasta and water", "Pizza and coffee", "Only coffee"]}', '{"correct": 0}', 1),
  ('00000000-0000-0000-0000-00000026002a', '00000000-0000-0000-0000-000000260028', 'true_false', '{"statement": "Anna wants a table for three."}', '{"answer": false}', 1),
  ('00000000-0000-0000-0000-00000026002c', '00000000-0000-0000-0000-00000026002b', 'listen_choose', '{"audio": "/content/restaurant/bill-please.mp3", "question": "What does the customer ask for?", "options": ["The bill", "The menu", "More water"]}', '{"correct": 0}', 1),
  ('00000000-0000-0000-0000-00000026002d', '00000000-0000-0000-0000-00000026002b', 'fill_blank', '{"text": "Can we have the ____, please?"}', '{"answers": ["bill"]}', 1),
  ('00000000-0000-0000-0000-00000026002f', '00000000-0000-0000-0000-00000026002e', 'mcq', '{"question": "You finished eating. You ask for the ...", "options": ["bill", "menu", "table"]}', '{"correct": 0}', 1),
  ('00000000-0000-0000-0000-000000260030', '00000000-0000-0000-0000-00000026002e', 'match', '{"left": ["menu", "water", "waiter"], "right": ["منو", "آب", "گارسون"]}', '{"pairs": [["menu", "منو"], ["water", "آب"], ["waiter", "گارسون"]]}', 1),
  ('00000000-0000-0000-0000-000000260031', '00000000-0000-0000-0000-00000026002e', 'sentence_builder', '{"words": ["I", "would", "like", "the", "pasta", "please"]}', '{"order": ["I", "would", "like", "the", "pasta", "please"]}', 1),
  ('00000000-0000-0000-0000-000000260032', '00000000-0000-0000-0000-00000026002e', 'listen_choose', '{"audio": "/content/restaurant/order-pasta.mp3", "question": "What does she order?", "options": ["The pasta", "The pizza", "The coffee"]}', '{"correct": 0}', 1),
  ('00000000-0000-0000-0000-000000260033', '00000000-0000-0000-0000-00000026002e', 'true_false', '{"statement": "“I would like” is polite."}', '{"answer": true}', 1)
